function atlas_location_name(id) {
    for place in atlas_places() { if place["id"] == id { return place["name"] } }
    return "Route inconnue"
}

function atlas_neighbor(page, delta) {
    local target = page + delta
    if target < 0 {return 2}
    if target > 2 {return 0}
    return target
}

function atlas_short(text, limit) {
    if len(text) > limit {return substring(text,0,limit-1)+"…"}
    return text
}

function atlas_wrap(text, limit) {
    local result = ""
    local line = ""
    for word in split(text," ") {
        if len(line)+len(word)+1 > limit and len(line) > 0 {
            set result = result + line + "\n"
            set line = word
        } else {
            if line == "" {set line = word}
            else {set line = line + " " + word}
        }
    }
    return result + line
}

function atlas_equipped_name(id) {
    for item in atlas_items() {if item["id"] == id {return item["name"]}}
    return "Aucun"
}

